BEGIN;

CREATE TABLE IF NOT EXISTS tbl_rol (
    id_rol BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    nombre_rol VARCHAR(100) NOT NULL UNIQUE,
    codigo VARCHAR(50) NOT NULL UNIQUE,
    descrip_rol TEXT NOT NULL,
    activo BOOLEAN NOT NULL DEFAULT TRUE,
    creado_en TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP,
    actualizado_en TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP
);

CREATE TABLE IF NOT EXISTS tbl_permiso (
    id_permiso BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    codigo_permiso VARCHAR(80) NOT NULL UNIQUE,
    accion_permiso VARCHAR(160) NOT NULL
);

CREATE TABLE IF NOT EXISTS tbl_rol_permiso (
    id_rol BIGINT NOT NULL,
    id_permiso BIGINT NOT NULL,
    PRIMARY KEY (id_rol, id_permiso),
    FOREIGN KEY (id_rol) REFERENCES tbl_rol (id_rol) ON DELETE CASCADE,
    FOREIGN KEY (id_permiso) REFERENCES tbl_permiso (id_permiso) ON DELETE CASCADE
);

CREATE TABLE IF NOT EXISTS tbl_empleado (
    id_emple BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    nombre_emple VARCHAR(120) NOT NULL,
    estado_emple VARCHAR(20) NOT NULL,
    correo_emple VARCHAR(254) NOT NULL UNIQUE,
    id_rol BIGINT NOT NULL,
    FOREIGN KEY (id_rol) REFERENCES tbl_rol (id_rol)
);

CREATE TABLE IF NOT EXISTS tbl_sesion (
    id_sesion BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    token_hash CHAR(64) NOT NULL UNIQUE,
    fecha_creacion TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP,
    fecha_expiracion TIMESTAMPTZ NOT NULL,
    fecha_revocacion TIMESTAMPTZ,
    id_empleado BIGINT NOT NULL,
    FOREIGN KEY (id_empleado) REFERENCES tbl_empleado (id_emple),
    CHECK (fecha_expiracion > fecha_creacion),
    CHECK (fecha_revocacion IS NULL OR fecha_revocacion >= fecha_creacion)
);

CREATE INDEX IF NOT EXISTS idx_sesion_empleado_vigente
    ON tbl_sesion (id_empleado, fecha_expiracion)
    WHERE fecha_revocacion IS NULL;

INSERT INTO tbl_rol (
    nombre_rol,
    codigo,
    descrip_rol,
    activo
)
VALUES
    ('Piloto', 'PILOTO', 'Personal responsable de una unidad asignada.', TRUE),
