ON CONFLICT (codigo) DO UPDATE
SET
    nombre_rol = EXCLUDED.nombre_rol,
    descrip_rol = EXCLUDED.descrip_rol,
    activo = EXCLUDED.activo,
    actualizado_en = CURRENT_TIMESTAMP;

